(function(){
  'use strict';
  var questions=[
    {d:'clarity',q:'Can your team clearly identify who the community serves, why those people should belong, and what business outcome it supports?',h:'Look for a specific group, a durable reason to participate, and an observable outcome such as retention, referrals, learning, advocacy, or opportunity.'},
    {d:'engagement',q:'Do members return and create meaningful value for one another without your team initiating every interaction?',h:'Look for repeat participation, member questions and answers, introductions, collaboration, contributions, or member-led activity.'},
    {d:'experiences',q:'Do your events or programs produce relationships, conversations, or actions that continue afterward?',h:'Use evidence such as follow-up conversations, projects, referrals, partnerships, repeat attendance, or member initiatives.'},
    {d:'content',q:'Does community activity consistently become useful content or stories that inspire further participation?',h:'Examples include member stories, clips, reports, lessons, case studies, discussions, submissions, and invitations to contribute.'},
    {d:'growth',q:'Can the right new people reliably discover, join, and become active through repeatable channels?',h:'Consider referrals, partnerships, search, events, direct invitations, onboarding, activation, and return behavior by source.'},
    {d:'operations',q:'Does your community have a clearly accountable owner, a repeatable operating cadence, and meaningful measurement?',h:'The operating system should cover ownership, programming, content, follow-up, and evidence that the community is becoming more valuable.'},
    {d:'proof',q:'What is the strongest evidence that your community is already creating value?',h:'Choose the level supported by outcomes you can point to today—not plans, intentions, membership totals, or impressions.',proof:true}
  ];
  var options=[
    {v:1,t:'No evidence yet',s:'This is absent or based on intention rather than observed behavior.'},
    {v:2,t:'Occasional evidence',s:'It happens, but inconsistently or because one person pushes it manually.'},
    {v:3,t:'Repeatable evidence',s:'It happens regularly through a defined practice with some gaps.'},
    {v:4,t:'Strong evidence',s:'It is intentional, repeatable, measured, and does not depend on heroics.'}
  ];
  var proofOptions=[
    {v:1,t:'No measurable outcome yet',s:'We do not yet have a concrete outcome we can attribute to the community.'},
    {v:2,t:'A few isolated examples',s:'We can point to individual wins, but they are not recurring or consistently produced.'},
    {v:3,t:'A recurring outcome',s:'We can repeatedly demonstrate a valuable member or organizational outcome.'},
    {v:4,t:'A measured business outcome',s:'The community consistently produces a measured outcome connected to the organization.'}
  ];
  var labels={clarity:'Community clarity',engagement:'Engagement',experiences:'Experiences',content:'Storytelling & content',growth:'Audience growth',operations:'Operations',proof:'Proven value'};
  var diagnoses={
    clarity:{name:'Audience Without a Community Promise',summary:'You may have access to people, but the reason they should belong, participate, and return is not yet specific or operational.',service:'Community Strategy & Activation',priorities:['Define the exact group the community exists to serve and the shared outcome connecting them.','Write a participation promise that is stronger than access, content, or networking.','Choose one measurable organizational outcome the community must support over the next 90 days.']},
    engagement:{name:'Community Without Participation',summary:'The structure exists, but members are not yet creating enough value with and for one another to make participation durable.',service:'Community Strategy & Activation',priorities:['Design one recurring member-to-member interaction that does not require a major event.','Give members a useful contribution role, not only material to consume.','Track repeat participation and contribution rather than total membership alone.']},
    experiences:{name:'Events Without Continuity',summary:'You can create moments that attract people, but the relationships and actions are not consistently continuing afterward.',service:'Virtual & Hybrid Experiences',priorities:['Give every experience a defined preparation, participation, and continuation path.','Install a follow-up ritual that reconnects participants within seven days.','Define the evidence of continued value before producing the next event.']},
    content:{name:'Content Without Participation',summary:'Your organization communicates, but community activity is not consistently becoming reusable content that invites further involvement.',service:'Storytelling & Content',priorities:['Build an event-to-content workflow with named owners and deadlines.','Create content from member questions, expertise, relationships, and outcomes.','Attach one explicit participation action to every major content series.']},
    growth:{name:'Community Without a Growth Engine',summary:'Existing relationships may be valuable, but discovery, entry, and member-led growth are not yet reliable.',service:'Audience Growth',priorities:['Identify the two acquisition paths producing the highest-quality participating members.','Create a specific referral or partner invitation for the right new people.','Measure activation and return behavior by acquisition source.']},
    operations:{name:'Community Without an Operating System',summary:'The ambition is stronger than the infrastructure. Ownership, cadence, workflow, or measurement is limiting viability.',service:'Community Operations',priorities:['Assign one accountable owner and define the decisions that person controls.','Create a 90-day programming, content, and follow-up cadence.','Use a small operating scorecard covering return, contribution, relationships, and opportunity.']}
  };
  var app=document.querySelector('[data-assessment-app]');if(!app)return;
  var startScreen=app.querySelector('[data-start-screen]'),form=app.querySelector('[data-assessment-form]'),panel=app.querySelector('[data-question-panel]'),leadGate=app.querySelector('[data-lead-gate]'),leadForm=app.querySelector('[data-lead-form]'),results=app.querySelector('[data-results]');
  var answers=new Array(questions.length).fill(null),index=0,computed=null;
  function show(el){el.hidden=false} function hide(el){el.hidden=true}
  function esc(v){return String(v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
  function answerOptions(item){return item.proof?proofOptions:options}
  function renderQuestion(){var item=questions[index],choices=answerOptions(item);panel.innerHTML='<legend tabindex="-1">'+esc(item.q)+'</legend><p class="question-help">'+esc(item.h)+'</p><div class="answer-options">'+choices.map(function(o){return '<label class="answer-option"><input type="radio" name="question_'+index+'" value="'+o.v+'" '+(answers[index]===o.v?'checked':'')+'><span><strong>'+esc(o.t)+'</strong><span>'+esc(o.s)+'</span></span></label>'}).join('')+'</div>';var p=Math.round(((index+1)/questions.length)*100);app.querySelector('[data-progress-label]').textContent='Question '+(index+1)+' of '+questions.length;app.querySelector('[data-progress-percent]').textContent=p+'%';app.querySelector('[data-progress-bar]').style.width=p+'%';app.querySelector('[data-back]').disabled=index===0;app.querySelector('[data-next]').textContent=index===questions.length-1?'Determine viability':'Continue';app.querySelector('[data-question-error]').textContent='';panel.querySelector('legend').focus()}
  function classification(overall,floor){if(floor<35||overall<40)return 'No viable community foundation yet';if(floor<50||overall<55)return 'Emerging community opportunity';if(floor<65)return 'Viable foundation with a critical constraint';if(overall<80)return 'Operationally viable community';return 'Community positioned to compound'}
  function calculate(){var dimensionKeys=['clarity','engagement','experiences','content','growth','operations'],dimensions={};dimensionKeys.forEach(function(k){var questionIndex=questions.findIndex(function(q){return q.d===k});dimensions[k]=answers[questionIndex]*25});var ranked=dimensionKeys.slice().sort(function(a,b){var difference=dimensions[a]-dimensions[b];return difference||dimensionKeys.indexOf(a)-dimensionKeys.indexOf(b)});var weakest=ranked[0],strongest=ranked[ranked.length-1],dimensionAverage=Object.values(dimensions).reduce(function(a,b){return a+b},0)/dimensionKeys.length,proofAnswer=answers[questions.findIndex(function(q){return q.proof})],proofScore=proofAnswer*25,overall=Math.round((dimensionAverage*.85)+(proofScore*.15)),floor=dimensions[weakest];return {overall:overall,dimensions:dimensions,weakest:weakest,strongest:strongest,floor:floor,proofScore:proofScore,classification:classification(overall,floor),diagnosis:diagnoses[weakest]}}
  function renderResults(){var d=computed;app.querySelector('[data-score]').textContent=d.overall;app.querySelector('[data-classification]').textContent=d.classification;app.querySelector('[data-diagnosis]').textContent=d.diagnosis.name;app.querySelector('[data-summary]').textContent=d.diagnosis.summary+' Recommended service path: '+d.diagnosis.service+'.';app.querySelector('[data-strongest]').textContent=labels[d.strongest]+' — '+d.dimensions[d.strongest]+'/100';app.querySelector('[data-constraint]').textContent=labels[d.weakest]+' — '+d.dimensions[d.weakest]+'/100';app.querySelector('[data-dimension-grid]').innerHTML=Object.keys(d.dimensions).map(function(k){return '<div class="dimension-result"><div><strong>'+esc(labels[k])+'</strong><span>'+d.dimensions[k]+'/100</span></div><meter min="0" max="100" low="50" high="65" optimum="100" value="'+d.dimensions[k]+'">'+d.dimensions[k]+' out of 100</meter></div>'}).join('');app.querySelector('[data-priorities]').innerHTML=d.diagnosis.priorities.map(function(p){return '<li>'+esc(p)+'</li>'}).join('');hide(leadGate);show(results);results.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}
  app.querySelector('[data-start]').addEventListener('click',function(){hide(startScreen);show(form);renderQuestion()});
  app.querySelector('[data-back]').addEventListener('click',function(){if(index>0){index-=1;renderQuestion()}});
  app.querySelector('[data-next]').addEventListener('click',function(){var selected=panel.querySelector('input:checked');if(!selected){app.querySelector('[data-question-error]').textContent='Choose the answer supported by the organization’s current evidence.';return}answers[index]=Number(selected.value);if(index<questions.length-1){index+=1;renderQuestion();return}computed=calculate();hide(form);show(leadGate);app.querySelector('[data-score-field]').value=String(computed.overall);app.querySelector('[data-diagnosis-field]').value=computed.diagnosis.name;app.querySelector('[data-classification-field]').value=computed.classification;app.querySelector('[data-strongest-field]').value=labels[computed.strongest]+' ('+computed.dimensions[computed.strongest]+'/100)';app.querySelector('[data-constraint-field]').value=labels[computed.weakest]+' ('+computed.dimensions[computed.weakest]+'/100)';app.querySelector('[data-priorities-field]').value=computed.diagnosis.priorities.join(' | ');app.querySelector('[data-dimensions-field]').value=JSON.stringify(Object.assign({},computed.dimensions,{proven_value:computed.proofScore}));app.querySelector('[data-answers-field]').value=questions.map(function(q,i){return 'Q'+(i+1)+' ['+labels[q.d]+'] '+q.q+' — '+answerOptions(q)[answers[i]-1].t}).join('\n');leadGate.scrollIntoView({behavior:'smooth',block:'start'})});
  panel.addEventListener('change',function(){app.querySelector('[data-question-error]').textContent=''})
  leadForm.querySelectorAll('input[type="url"]').forEach(function(input){function normalize(){var value=String(input.value||'').trim();if(value&&!/^[a-z][a-z0-9+.-]*:/i.test(value)&&value.includes('.'))input.value='https://'+value.replace(/^\/+/, '')}input.addEventListener('blur',normalize);input.addEventListener('keydown',function(e){if(e.key==='Enter')normalize()})});
  leadForm.addEventListener('submit',function(event){event.preventDefault();if(!leadForm.reportValidity())return;var status=app.querySelector('[data-lead-status]'),button=leadForm.querySelector('button[type=submit]'),original=button.textContent;button.disabled=true;button.textContent='Sending…';status.dataset.state='pending';status.textContent='Sending your assessment to West Peek…';fetch(leadForm.action,{method:'POST',body:new FormData(leadForm),headers:{Accept:'application/json'}}).then(function(r){return r.json().catch(function(){return null}).then(function(b){return {ok:r.ok,b:b}})}).then(function(x){if(!(x.ok&&x.b&&x.b.ok===true))throw new Error('delivery_failed');status.dataset.state='ok';status.textContent='Your assessment was delivered to West Peek. Your result is ready below.';renderResults()}).catch(function(){status.dataset.state='error';status.replaceChildren(document.createTextNode('We could not deliver your assessment, so nothing was submitted. Please email '));var link=document.createElement('a');link.href='mailto:scooter@westpeek.ventures';link.textContent='scooter@westpeek.ventures';status.appendChild(link);status.appendChild(document.createTextNode('.'))}).finally(function(){button.disabled=false;button.textContent=original})});
})();
